// LIMIT = 0 → все строки (полный перепрог)
const LIMIT = 0;
const rows = $input.all();
const out = [];
for (let i = 0; i < rows.length; i++) {
  const r = rows[i].json || {};
  const ffId = String(r['ID встречи (Fireflies)'] || '').trim();
  if (!ffId) continue;
  // ПЕРЕПРОГ ПО ВСЕМ: фильтр «только пустые» снят — перезаписываем все строки с transcriptId
  const ffBody = { query: 'query Transcript($transcriptId: String!) { transcript(id: $transcriptId) { title date duration sentences { speaker_name text } } }', variables: { transcriptId: ffId } };
  out.push({ json: {
    row_number: r.row_number,
    ffId: ffId,
    existingManager: String(r['Менеджер'] || '').trim(),
    existingContact: String(r['Имя контакта'] || '').trim(),
    ffBody: ffBody
  } });
  if (LIMIT && out.length >= LIMIT) break;
}
return out;

const responses = $input.all();
const rows = $('Prep Rows').all();
const out = [];
for (let i = 0; i < responses.length; i++) {
  const ft = responses[i].json || {};
  const ctx = (rows[i] && rows[i].json) ? rows[i].json : {};
  const data = (ft.data && ft.data.transcript) ? ft.data.transcript : (ft.transcript || {});
  const sentences = (data && data.sentences) ? data.sentences : [];
  if (!sentences.length) continue;
  let transcriptText = '';
  for (let j = 0; j < sentences.length; j++) { const s = sentences[j] || {}; transcriptText += (s.speaker_name || 'Спикер') + ': ' + (s.text || '') + '\n'; }
  const title = data.title || '';
  const date = data.date || '';
  const managers = [
 'Анна (Соколова Анна / Анна / Аня)',
 'Дмитрий (Орлов Дмитрий / Дмитрий / Дима)',
 'Елена (Белова Елена / Елена / Лена)',
 'Сергей (Новиков Сергей / Сергей / Серёжа)',
 'Наталья (Кравцова Наталья / Наталья / Наташа)'
];
  const system = [
    'Ты — ассистент, анализирующий транскрипт деловой встречи с клиентом на русском. Встреча уже классифицирована как целевая — переклассифицировать не нужно. Извлеки ТОЛЬКО указанные ниже поля.',
    '',
    'Менеджеры и руководители НАШЕЙ стороны и формы их имени: ' + managers.join('; ') + '.',
    '',
    'КАК ОПРЕДЕЛИТЬ manager и contact_name:',
    '- НАШ менеджер — тот, кто ПРОВОДИТ встречу и ЗАДАЁТ вопросы (про бизнес собеседника, про сотрудничество с нами, обратную связь, пожелания). КЛИЕНТ — тот, ЧЕЙ бизнес обсуждают и кто ОТВЕЧАЕТ на эти вопросы.',
    '- Основной источник имени менеджера — поле «Текущий Менеджер в таблице» (дано ниже). По умолчанию верни именно его (нормализовав к канону). Меняй его ТОЛЬКО если из транскрипта однозначно следует, что встречу вёл другой человек из списка наших менеджеров.',
    '- КОЛЛИЗИЯ ИМЁН (важно): если КЛИЕНТА зовут так же, как кого-то из списка наших менеджеров (например, клиента тоже зовут Анна, Дмитрий, Сергей и т.п.) — он ВСЁ РАВНО КЛИЕНТ, а не наш менеджер. Само по себе совпадение имени НЕ делает участника нашим менеджером. Имя из списка засчитывается менеджером только если этот человек задаёт вопросы.',
    '- manager — каноническое полное имя менеджера (первое слово до скобок из списка), несколько через запятую если наших на встрече несколько. contact_name — имя(имена) со стороны КЛИЕНТА, несколько через запятую. Имена не выдумывай; если не названо — оставь как в текущем значении строки или пусто.',
    '',
    'Поля для извлечения:',
    '- q8_wishes — что клиент сам озвучил или попросил: новые услуги/инструменты у нас; изменения в работе (сроки, формат, отчётность); любые явные пожелания и просьбы.',
    '- company_summary — сводка о компании клиента: чем занимается, масштаб, направления, ситуация в бизнесе.',
    '- growth_opportunities — аналитический срез про клиента и его бизнес: куда движется, намерения и тренды, спящий потенциал, и зоны, где МЫ могли бы вырасти ВНЕ текущих услуг (наши услуги: перечислите свои услуги). Это твой вывод из контекста, НЕ дублируй сюда прямые просьбы клиента (они в q8_wishes). Помечай: сказано прямо или это предположение.',
    '',
    'Верни СТРОГО валидный JSON без markdown по схеме:',
    '{ "manager":"", "contact_name":"", "q8_wishes":"", "company_summary":"", "growth_opportunities":"" }'
  ].join('\n');
  const user = 'Заголовок встречи: ' + title + '\nДата: ' + date + '\nТекущий Менеджер в таблице (это НАШ менеджер — основной якорь): ' + (ctx.existingManager || '—') + '\nТекущий Контакт в таблице (сторона клиента): ' + (ctx.existingContact || '—') + '\n\nТранскрипт:\n' + transcriptText;
  const openaiBody = { model: 'gpt-5.4', messages: [ { role: 'system', content: system }, { role: 'user', content: user } ], response_format: { type: 'json_object' } };
  out.push({ json: { row_number: ctx.row_number, ffId: ctx.ffId, openaiBody: openaiBody } });
}
return out;

const responses = $input.all();
const bp = $('Build Prompt').all();
const MGR = [
 {full:'Анна',    keys:['анна','аня','соколова']},
 {full:'Дмитрий', keys:['дмитрий','дима','орлов']},
 {full:'Елена',   keys:['елена','лена','белова']},
 {full:'Сергей',  keys:['сергей','сережа','новиков']},
 {full:'Наталья', keys:['наталья','наташа','кравцова']}
];
const normMgr = (raw) => {
  if (!raw) return '';
  const res = [];
  String(raw).split(',').forEach((part) => {
    const words = part.toLowerCase().replace(/ё/g,'е').split(/[^а-я]+/).filter(Boolean);
    let canon = '';
    for (const m of MGR) { if (m.keys.some((k) => words.includes(k))) { canon = m.full; break; } }
    const val = canon || part.trim();
    if (val && res.indexOf(val) === -1) res.push(val);
  });
  return res.join(', ');
};
const out = [];
for (let i = 0; i < responses.length; i++) {
  const resp = responses[i].json || {};
  const ctx = (bp[i] && bp[i].json) ? bp[i].json : {};
  let content = '';
  try { content = resp.choices[0].message.content || ''; } catch (e) { content = ''; }
  content = content.replace(/```json/gi,'').replace(/```/g,'').trim();
  let parsed = null;
  try { parsed = JSON.parse(content); } catch (e) { parsed = null; }
  if (!parsed) continue;
  const upd = { row_number: ctx.row_number };
  if (parsed.manager) upd['Менеджер'] = normMgr(parsed.manager);
  if (parsed.contact_name) upd['Имя контакта'] = parsed.contact_name;
  upd['Предложения и пожелания клиента'] = parsed.q8_wishes || '';
  upd['О компании'] = parsed.company_summary || '';
  upd['Перспективы и зоны роста'] = parsed.growth_opportunities || '';
  out.push({ json: upd });
}
return out;

const rows = $('Read Sheet').all();
const out = [];
const seen = {};
for (let i = 0; i < rows.length; i++) {
  const r = rows[i].json || {};
  const ffId = String(r['ID встречи (Fireflies)'] || '').trim();
  if (!ffId || seen[ffId]) continue;
  seen[ffId] = true;
  const ref = (String(r['Менеджер'] || '').trim() + ' - ' + String(r['Дата встречи'] || '').trim());
  out.push({ json: { ffId: ffId, refName: ref } });
}
return out;
